import { jsonSchemaToType } from "/app/ark/json-schema/index.ts"

const t = jsonSchemaToType({
	$defs: {
		a: { anyOf: [ { type: "string" }, { type: "object", properties: { b: { $ref: "#/$defs/b" } } } ] },
		b: { anyOf: [ { type: "number" }, { type: "object", properties: { a: { $ref: "#/$defs/a" } } } ] }
	},
	$ref: "#/$defs/a"
})
console.log("mutual", t.expression)
console.log("str", t.allows("x"))
console.log("num nested", t.allows({ b: { a: "x" } }))
console.log("deep", t.allows({ b: { a: { b: 1 } } }))
console.log("bad", t.allows({ b: { a: true } }))

const d = jsonSchemaToType({
	type: "object",
	properties: { a: { type: "string" }, b: { type: "string" }, c: { type: "string" }, d: { type: "number" } },
	dependentRequired: { a: ["b"] },
	dependentSchemas: { c: { properties: { d: { type: "number" } }, required: ["d"] } },
	dependencies: { a: ["c"] }
})
console.log("deps all", d.allows({a:"x",b:"y",c:"z",d:1}), d.allows({a:"x"}), d.allows({c:"z",d:1}), d.allows({c:"z",d:"x"}))
EOF
timeout 60 pnpm ts /tmp/json-schema-scratch.ts 2>&1 | tail -20

cd /app && cat > /tmp/json-schema-scratch.ts <<'EOF'
import { jsonSchemaToType } from "/app/ark/json-schema/index.ts"

// obj refs a non-raw def (object enum) -> obj should be parsed eagerly
const t = jsonSchemaToType({ $defs: { e: { enum: [{a:1}, [1,2]] }, obj: { type: "object", properties: { x: { $ref: "#/$defs/e" } }, required: ["x"] } }, $ref: "#/$defs/obj" })
console.log("expr", t.expression)
console.log("x={a:1}", t.allows({x:{a:1}}))
console.log("x=3", t.allows({x:3}))

// recursion still works
const r = jsonSchemaToType({ $defs: { tree: { type: "object", properties: { name: { type: "string" }, child: { $ref: "#/$defs/tree" } }, required: ["name"] } }, $ref: "#/$defs/tree" })
console.log("recursion", r.expression, r.allows({name:"x",child:{name:"y"}}))

// anyOf recursion
const a = jsonSchemaToType({ $defs: { node: { anyOf: [ { type: "string" }, { type: "object", properties: { child: { $ref: "#/$defs/node" } } } ] } }, $ref: "#/$defs/node" })
console.log("anyOf", a.expression, a.allows({child:{child:"x"}}))

// array of refs
const arr = jsonSchemaToType({ $defs: { node: { type: "object", properties: { children: { type: "array", items: { $ref: "#/$defs/node" } } } } }, $ref: "#/$defs/node" })
console.log("array refs", arr.expression, arr.allows({children:[{}]}))
EOF
